{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Across all four datasets, shorten the causal interest mean half-life from four interactions to three while retaining the 0.8 GRU-state and 0.2 interest-mean blend. This isolates recency sensitivity while preserving padding exclusion, causal prefixes, final-real-position inference, and all other model and training settings.",
      "edits": [
        {
          "find": "        weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 4.0)",
          "replace": "        weights = torch.exp2(-distances.clamp(min=0).to(out.dtype) / 3.0)"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_4\",",
          "replace": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_4\":",
          "replace": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":"
        }
      ]
    }
  ],
  "change_summary": "Change only causal pooling half-life from four interactions to three and synchronize checkpoint metadata with the embedded predictor loader. Retain one GRU4Rec model per dataset."
}
